//! The GTK bindings, generated by the build.
//!
//! `zig-gobject` reads the GIR files installed on this machine and writes Zig
//! modules, one per GObject namespace. It is a pinned dependency (see
//! build.zig.zon), which is what makes the table below safe to carry here: it
//! describes the pinned revision's output and cannot drift from it silently.
//!
//! This lives in a build script rather than in `tools/` because decision 10
//! says `zig build` is the only build entry point, and a script that has to run
//! before it is a second one. Zig resolves build.zig.zon before build.zig runs,
//! so the bindings can only be consumed as a dependency or generated here;
//! generating them here is what keeps `zig build` sufficient on its own.

const std = @import("std");

/// The modules the generated bindings publish, addressed by the name Zig code
/// imports them as.
pub const Bindings = struct {
    names: []const []const u8,
    modules: []const *std.Build.Module,

    pub fn module(self: Bindings, name: []const u8) *std.Build.Module {
        for (self.names, self.modules) |candidate, candidate_module| {
            if (std.mem.eql(u8, candidate, name)) return candidate_module;
        }
        std.debug.panic("no binding module named {s}", .{name});
    }
};

/// Generates the bindings and creates one module per namespace.
pub fn add(
    b: *std.Build,
    target: std.Build.ResolvedTarget,
    optimize: std.builtin.OptimizeMode,
) Bindings {
    const codegen = b.dependency("zig_gobject", .{ .target = b.graph.host, .optimize = .Debug });

    const generate = b.addRunArtifact(codegen.artifact("translate-gir"));
    // The distribution's GIR files, plus the two this machine lacks. The
    // directory is asked of pkg-config rather than written down, so the build
    // does not assume where a distribution puts them.
    const gir_dir = std.mem.trim(u8, b.run(&.{ "pkg-config", "--variable=girdir", "gobject-introspection-1.0" }), " \n");
    generate.addPrefixedDirectoryArg("--gir-dir=", .{ .cwd_relative = gir_dir });
    generate.addPrefixedDirectoryArg("--gir-dir=", extraGirs(b));
    // The generator carries corrections and hand-written overrides of its own;
    // they sit in its source tree, next to the pinned revision.
    generate.addPrefixedDirectoryArg("--gir-fixes-dir=", codegen.builder.path("gir-fixes"));
    generate.addPrefixedDirectoryArg("--bindings-dir=", codegen.builder.path("binding-overrides"));
    generate.addPrefixedDirectoryArg("--extensions-dir=", codegen.builder.path("extensions"));
    const output = generate.addPrefixedOutputDirectoryArg("--output-dir=", "bindings");
    // Gtk-4.0 pulls in every namespace the shell reaches.
    generate.addArg("Gtk-4.0");

    const names = b.allocator.alloc([]const u8, descriptions.len) catch @panic("OOM");
    const modules = b.allocator.alloc(*std.Build.Module, descriptions.len) catch @panic("OOM");

    // Two passes: every module has to exist before any is wired to the others,
    // because the generated namespaces import each other in a cycle.
    for (descriptions, 0..) |description, i| {
        const module = b.createModule(.{
            .root_source_file = output.path(b, b.fmt("src/{s}/{s}.zig", .{ description.name, description.name })),
            .target = target,
            .optimize = optimize,
        });
        for (description.libraries) |library| module.linkSystemLibrary(library, .{});
        names[i] = description.name;
        modules[i] = module;
    }
    for (descriptions, 0..) |description, i| {
        for (description.imports) |import| {
            modules[i].addImport(import, lookup(names, modules, import));
        }
    }

    return .{ .names = names, .modules = modules };
}

fn lookup(names: []const []const u8, modules: []const *std.Build.Module, name: []const u8) *std.Build.Module {
    for (names, modules) |candidate, candidate_module| {
        if (std.mem.eql(u8, candidate, name)) return candidate_module;
    }
    std.debug.panic("the bindings table imports unknown module {s}", .{name});
}

/// cairo and freetype2 ship typelibs but no XML here, and Gtk-4.0.gir depends
/// on both, so their GIR files are regenerated before the generator runs.
fn extraGirs(b: *std.Build) std.Build.LazyPath {
    const run = b.addSystemCommand(&.{"sh"});
    run.addFileArg(b.path("build/extra-girs.sh"));
    return run.addOutputDirectoryArg("girs");
}

const Description = struct {
    name: []const u8,
    imports: []const []const u8,
    libraries: []const []const u8,
};

/// The pinned revision's module graph, transcribed from the build.zig the
/// generator writes alongside the bindings. Every namespace imports itself (the
/// generated file is reached by name from its own `ext` helpers) and `compat`;
/// the libraries are what that namespace's C library needs.
const descriptions = [_]Description{
    // Shared by every namespace; the generator makes this one with
    // `createModule` rather than `addModule`, so it was not in the module list
    // the table was transcribed from.
    .{ .name = "compat", .imports = &.{}, .libraries = &.{} },
    .{ .name = "gtk4", .imports = &.{ "cairo1", "compat", "freetype22", "gdk4", "gdkpixbuf2", "gio2", "glib2", "gmodule2", "gobject2", "graphene1", "gsk4", "gtk4", "harfbuzz0", "pango1", "pangocairo1" }, .libraries = &.{"gtk4"} },
    .{ .name = "gsk4", .imports = &.{ "cairo1", "compat", "freetype22", "gdk4", "gdkpixbuf2", "gio2", "glib2", "gmodule2", "gobject2", "graphene1", "gsk4", "harfbuzz0", "pango1", "pangocairo1" }, .libraries = &.{"gtk4"} },
    .{ .name = "graphene1", .imports = &.{ "compat", "glib2", "gobject2", "graphene1" }, .libraries = &.{"graphene-gobject-1.0"} },
    .{ .name = "gobject2", .imports = &.{ "compat", "glib2", "gobject2" }, .libraries = &.{"gobject-2.0"} },
    .{ .name = "glib2", .imports = &.{ "compat", "glib2" }, .libraries = &.{"glib-2.0"} },
    .{ .name = "gdk4", .imports = &.{ "cairo1", "compat", "freetype22", "gdk4", "gdkpixbuf2", "gio2", "glib2", "gmodule2", "gobject2", "harfbuzz0", "pango1", "pangocairo1" }, .libraries = &.{"gtk4"} },
    .{ .name = "cairo1", .imports = &.{ "cairo1", "compat", "glib2", "gobject2" }, .libraries = &.{"cairo-gobject"} },
    .{ .name = "pangocairo1", .imports = &.{ "cairo1", "compat", "freetype22", "gio2", "glib2", "gmodule2", "gobject2", "harfbuzz0", "pango1", "pangocairo1" }, .libraries = &.{"pangocairo"} },
    .{ .name = "pango1", .imports = &.{ "cairo1", "compat", "freetype22", "gio2", "glib2", "gmodule2", "gobject2", "harfbuzz0", "pango1" }, .libraries = &.{"pango"} },
    .{ .name = "harfbuzz0", .imports = &.{ "compat", "freetype22", "glib2", "gobject2", "harfbuzz0" }, .libraries = &.{ "harfbuzz", "harfbuzz-gobject" } },
    .{ .name = "freetype22", .imports = &.{ "compat", "freetype22" }, .libraries = &.{} },
    .{ .name = "gio2", .imports = &.{ "compat", "gio2", "glib2", "gmodule2", "gobject2" }, .libraries = &.{"gio-2.0"} },
    .{ .name = "gmodule2", .imports = &.{ "compat", "glib2", "gmodule2" }, .libraries = &.{"gmodule-2.0"} },
    .{ .name = "gdkpixbuf2", .imports = &.{ "compat", "gdkpixbuf2", "gio2", "glib2", "gmodule2", "gobject2" }, .libraries = &.{"gdk-pixbuf-2.0"} },
};